from pathlib import Path
from html import escape
import json
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'REVISAO-02'
palettes=json.loads((OUT/'paletas.json').read_text(encoding='utf-8'))
def im(f,cls=''):return f'<img class="{cls}" src="{f}" alt="{escape(Path(f).stem)}">'
pages=[]
def page(kicker,title,body,id):
 n=len(pages)+1
 pages.append(f'<div class="sheet" id="{id}"><section class="page"><header>{kicker}</header><h1>{title}</h1>{body}<footer><span>AUREVI · ESTUDOS DE DIREÇÃO 02 · 04/11/2026</span><span>{n:02}</span></footer></section></div>')

logos=[('01','editorial','Editorial','Bodoni Moda: contraste forte e desenho de moda editorial. Mais impacto; os traços finos precisam de atenção nas reduções.'),('02','assinatura','Assinatura','Cormorant Garamond, com espaçamento trabalhado e gesto no R. Minha recomendação para começar: aproxima a elegância da referência e traz um detalhe próprio.'),('03','contemporanea','Contemporânea','Italiana: alongada, leve e com recortes particulares. Uma alternativa mais limpa, mantendo personalidade no desenho.')]
rows=''.join(f'<article class="logo-row"><div>{im("logos/"+n+"-"+slug+"-azul.svg")}</div><aside><span class="number">{n}</span><h2>{title}</h2><p>{text}</p></aside></article>' for n,slug,title,text in logos)
page('01 / UM NOME COM MAIS ASSINATURA','Três novas escritas.',f'<div class="logo-rows">{rows}</div><p class="footnote">Estudos em caixa alta para comparar o desenho do nome. A cor usada aqui é a mesma nas três opções; a paleta pode ser escolhida separadamente.</p>','escritas')

cards=''
for p in palettes:
 cs=p['colors']
 cards+=f'<article class="palette"><div class="palette-brand" style="background:{cs[0]}">{im("logos/01-editorial-branco.svg")}<div class="gold-line" style="background:{cs[2]}"></div></div><div class="palette-copy"><span class="number">{p["id"]}</span><h2>{p["name"]}</h2><p>{p["reason"]}</p><div class="swatches">'+''.join(f'<div><i style="background:{c}"></i><b>{n}</b><small>{c}</small></div>' for c,n in zip(cs,p['names']))+'</div></div></article>'
page('02 / AURE = OURO · VI = VIDA','Ouro no detalhe. Vida na presença.',f'<div class="palette-grid">{cards}</div><p class="footnote">O ouro é um acento, não uma obrigação de pintar tudo de dourado. Nas fotos, “vida” aparece nas roupas, nas cores e no movimento. Tons digitais não simulam hot stamping real.</p>','paletas')

avs=''.join(f'<article>{im("av/0"+str(i)+".svg")}<h2>{title}</h2><p>{desc}</p></article>' for i,title,desc in [(1,'O que você gostou','Mantém o símbolo da primeira versão como ponto de comparação.'),(2,'Mais contraste','Afina alguns encontros e acrescenta pequenas terminações para conversar com as novas serifas.'),(3,'Curva mais leve','Preserva a separação entre A e V, com uma saída mais leve no topo do V.')])
page('03 / PRESERVAR O QUE FUNCIONOU','O AV continua no centro da ideia.',f'<div class="av-grid">{avs}</div><p class="footnote">O símbolo pode funcionar sem acompanhar toda escrita. O refinamento final depende da opção tipográfica escolhida; ainda são estudos, não uma substituição aprovada.</p>','av')

links=json.loads((OUT/'mockups/links.json').read_text(encoding='utf-8'))
mockups=''.join(f'<figure>{im("mockups/"+r["filename"])}<figcaption><a href="{escape(r["editUrl"],quote=True)}">{label} · abrir no Kittl ↗</a></figcaption></figure>' for r,label in zip(links,['Sacola estruturada e alça de cordão','Embalagem de loja, em uso']))
page('04 / APLICAÇÕES DE BOUTIQUE','Um contexto mais próximo da loja.',f'<div class="mockup-grid">{mockups}<figure class="tag">{im("aplicacoes/tag-estudo.svg")}<figcaption>Tag de vestuário · estudo azul + ouro</figcaption></figure></div><p class="footnote">Novos mockups criados no Kittl, em papel claro e alças de loja. A tag é um estudo plano. Sem kraft, ecobag, flores ou cenário rústico.</p>','aplicacoes')

photo=OUT/'editorial/vestido-estudo.png'
if photo.exists():
 page('05 / DIREÇÃO DE FOTOGRAFIA','A roupa conduz a imagem.',f'<div class="photo-layout"><figure>{im("editorial/vestido-estudo.png")}<figcaption>Estudo de imagem gerado por IA a partir da referência de vestido enviada por você.</figcaption></figure><div><h2>O que muda</h2><p>Vestido ajustado, drapeado lateral e produção com acessórios. A fotografia passa a valorizar o caimento, a construção e a presença do look.</p><h2>Modelo e cenário</h2><p>Outra modelo e fundo liso de estúdio, com luz limpa. A imagem mantém a proposta da peça de referência, sem carregar a ambientação da concorrente.</p><h2>O que conferir depois</h2><p>É um estudo visual. Para anunciar uma peça real, comparar tecido, cor, recortes, comprimento e acabamento com o produto da loja.</p></div></div>','fotografia')

page('06 / LEITURA DA DONNA E RECOMENDAÇÃO','Mais moda. Mais presença. Mais Aurevi.',f'''
<div class="recommendation"><div><h2>O que observei na Donna</h2><p>Na amostra pública aberta com Playwright, aparecem jeans e polo junto de vestidos com renda, drapeado, recortes e conjuntos mais produzidos. As fotos mostram a roupa em modelos e os detalhes do look.</p><p>O início do feed tem uma campanha de Natal em vermelho; isso é uma campanha pontual, não motivo para deduzir a paleta permanente da marca.</p><p class="source">Fontes: <a href="https://www.instagram.com/donna.oficial/">Instagram da Donna</a> e <a href="https://www.lojadonnaoficial.com.br/">catálogo da loja</a>, consultados em 04/11/2026. Análise visual da amostra carregada, sem acesso a todos os vídeos ou posts.</p></div><div class="choice"><span class="number">MINHA RECOMENDAÇÃO</span><h2>Escrita 02<br>+ paleta 01</h2><p>O gesto no nome traz o “tcham” que faltava. Azul noite, porcelana e ouro suave aproximam a Aurevi da elegância que você mostrou na referência.</p><p>Se quiser uma marca mais quente e marcante, escolheria a mesma escrita com a paleta 02, bordô e champagne.</p><p class="source">As propostas são combináveis. Esta rodada serve para escolher a nova base; o kit anterior foi preservado.</p></div></div>''','direcao')

css='''@font-face{font-family:M;src:url('../ENTREGA/06-fontes/Manrope.ttf');font-weight:200 800}@font-face{font-family:C;src:url('fontes/CormorantGaramond.ttf');font-weight:300 700}*{box-sizing:border-box}body{margin:0;background:#d9dce0;color:#233a57;font-family:M,sans-serif}nav{height:68px;position:sticky;top:0;z-index:5;background:#233a57;color:#faf7f2;display:flex;align-items:center;gap:25px;padding:0 32px;font-size:14px}nav b{letter-spacing:3px}nav a{color:inherit;text-decoration:none}nav .grow{flex:1}main{padding:28px}.sheet{width:calc(1800px * var(--s,1));height:calc(1100px * var(--s,1));margin:0 auto 28px;position:relative}.page{width:1800px;height:1100px;background:#faf7f2;position:absolute;transform:scale(var(--s,1));transform-origin:0 0;padding:65px 85px;overflow:hidden}header{font-size:19px;letter-spacing:3px;font-weight:500}h1{font:500 78px/1.04 C,serif;margin:20px 0 30px;letter-spacing:-1px}h2{font:500 40px/1.12 C,serif;margin:10px 0 15px}p{font-size:25px;line-height:1.5;margin:0 0 22px}img{display:block;max-width:100%}footer{position:absolute;left:85px;right:85px;bottom:28px;border-top:1px solid #233a5730;display:flex;justify-content:space-between;padding-top:14px;font-size:13px;letter-spacing:2px}.number{font-size:17px;letter-spacing:3px;font-weight:600}.footnote{font-size:20px;line-height:1.5;margin:22px 0 0}.logo-rows{display:grid;gap:10px}.logo-row{display:grid;grid-template-columns:1080px 1fr;align-items:center;gap:55px;border-top:1px solid #233a5722;padding:10px 0;height:230px}.logo-row img{height:220px;width:100%;object-fit:contain}.logo-row h2{font-size:34px;margin:5px 0 9px}.logo-row p{font-size:21px;line-height:1.4;margin:0}.palette-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:28px}.palette{border:1px solid #233a5722}.palette-brand{height:280px;padding:58px 28px 24px}.palette-brand img{width:100%;height:160px;object-fit:contain}.gold-line{width:70px;height:3px;margin:16px auto}.palette-copy{padding:25px 28px}.palette h2{font-size:36px;margin-bottom:15px}.palette p{font-size:22px;line-height:1.43;min-height:160px}.swatches{display:flex;gap:12px;margin-top:28px}.swatches>div{flex:1}.swatches i{display:block;height:90px;border:1px solid #233a5722}.swatches b{display:block;font-size:14px;white-space:nowrap;margin-top:12px}.swatches small{font-size:16px;display:block;margin-top:7px}.av-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:45px}.av-grid img{width:100%;height:480px;object-fit:contain}.av-grid h2{font-size:34px}.av-grid p{font-size:23px}.mockup-grid{display:grid;grid-template-columns:650px 650px 1fr;gap:30px}.mockup-grid img{width:100%;height:650px;object-fit:contain}.mockup-grid .tag img{height:570px;margin-top:40px}figure{margin:0}figcaption{font-size:17px;line-height:1.5;margin-top:14px}a{color:inherit;text-underline-offset:4px}.photo-layout{display:grid;grid-template-columns:630px 1fr;gap:100px}.photo-layout img{width:525px;height:760px;object-fit:contain}.photo-layout figcaption{font-size:20px;max-width:580px}.photo-layout h2{font-size:43px;margin-top:20px}.photo-layout p{font-size:26px}.recommendation{display:grid;grid-template-columns:1fr 1fr;gap:100px;padding-top:15px}.recommendation h2{font-size:48px}.recommendation .choice{background:#233a57;color:#faf7f2;padding:40px 45px;border-top:6px solid #be9b57}.choice h2{font-size:77px;margin:35px 0}.source{font-size:20px;line-height:1.5;margin-top:35px}.recommendation .choice p{font-size:24px}.choice .number{color:#e0c798}@page{size:1800px 1100px;margin:0}@media print{body{background:none}nav{display:none}main{padding:0}.sheet{width:1800px!important;height:1100px!important;margin:0;break-after:page}.sheet:last-child{break-after:auto}.page{position:relative;transform:none!important}*{-webkit-print-color-adjust:exact;print-color-adjust:exact}}@media(max-width:650px){nav{padding:0 15px;gap:15px;font-size:12px}nav .hide{display:none}main{padding:12px}.sheet{margin-bottom:12px}}'''
html='<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Aurevi — novos estudos</title><style>'+css+'</style></head><body><nav><b>AUREVI / 02</b><a href="#escritas">Escritas</a><a href="#paletas">Paletas</a><a class="hide" href="#av">AV</a><a class="hide" href="#aplicacoes">Aplicações</a><span class="grow"></span><a href="Estudos-Aurevi-02.pdf">PDF ↗</a></nav><main>'+''.join(pages)+'''</main><script>function fit(){document.documentElement.style.setProperty('--s',Math.min(1,(innerWidth-(innerWidth<650?24:56))/1800))}fit();addEventListener('resize',fit)</script></body></html>'''
(OUT/'ESTUDOS.html').write_text(html,encoding='utf-8')
print('Apresentação criada:',len(pages),'páginas.')
